#!/usr/bin/env python3
# SPDX-License-Identifier: MIT
"""Build authored M6 decks with python-pptx; preserve complete Office OPC packages.

Run with --check to compare every generated byte. Downloaded originals are never
rewritten. Geometry is in points; no reference colors or test sample points are
stored in the decks or manifests.
"""
import argparse
from datetime import datetime, timezone
from io import BytesIO
import json
from pathlib import Path
from zipfile import ZIP_STORED, ZipFile, ZipInfo

from PIL import Image, ImageDraw
from pptx import Presentation
from pptx.dml.color import RGBColor
from pptx.enum.dml import MSO_THEME_COLOR
from pptx.enum.shapes import MSO_AUTO_SHAPE_TYPE as SHAPE
from pptx.enum.shapes import MSO_CONNECTOR
from pptx.enum.text import MSO_ANCHOR
from pptx.oxml.ns import qn
from pptx.oxml.xmlchemy import OxmlElement
from pptx.util import Pt

HERE = Path(__file__).resolve().parent
PALETTE = ('245A81', 'D97B28', '4C8250', '805BA3', '269CA8', 'D1A52B')


def xml(tag, **attrs):
    node = OxmlElement(tag)
    for name, value in attrs.items():
        node.set(name, str(value))
    return node


def presentation(wide=True):
    deck = Presentation()
    deck.slide_width, deck.slide_height = Pt(960 if wide else 720), Pt(540)
    deck.core_properties.title = 'EXReader M6 authored presentation corpus'
    deck.core_properties.author = 'EXReader contributors'
    deck.core_properties.subject = 'MIT licensed authored compatibility corpus'
    deck.core_properties.created = datetime(2020, 1, 1, tzinfo=timezone.utc)
    deck.core_properties.modified = datetime(2020, 1, 1, tzinfo=timezone.utc)
    deck.core_properties.last_modified_by = 'EXReader contributors'
    deck.core_properties.revision = 1
    return deck


def slide(deck):
    return deck.slides.add_slide(deck.slide_layouts[6])


def format_paragraph(paragraph, text, size=24, color='172D3E', bold=False):
    paragraph.text = text
    paragraph.space_before = Pt(0)
    paragraph.space_after = Pt(12)
    for run in paragraph.runs:
        run.font.name = 'Arial'
        run.font.size = Pt(size)
        run.font.bold = bold
        run.font.color.rgb = RGBColor.from_string(color)


def text(shapes, value, box, size=24, color='172D3E', bold=False):
    shape = shapes.add_textbox(*(Pt(v) for v in box))
    frame = shape.text_frame
    frame.word_wrap = True
    frame.margin_left = frame.margin_right = Pt(0)
    frame.margin_top = frame.margin_bottom = Pt(0)
    frame.vertical_anchor = MSO_ANCHOR.TOP
    for i, value_line in enumerate(value.split('\n')):
        format_paragraph(frame.paragraphs[0] if not i else frame.add_paragraph(),
                         value_line, size, color, bold)
    return shape


def title(page, value, width=864):
    return text(page.shapes, value, (48, 28, width, 66), 32, bold=True)


def solid(shapes, geometry, box, color, alpha=None):
    shape = shapes.add_shape(geometry, *(Pt(v) for v in box))
    shape.fill.solid()
    shape.fill.fore_color.rgb = RGBColor.from_string(color)
    if alpha is not None:
        shape._element.spPr.solidFill[0].append(xml('a:alpha', val=alpha))
    shape.line.fill.background()
    return shape


def illustration():
    """An original landscape illustration, saved as a level-0 PNG."""
    im = Image.new('RGB', (240, 160), '#90C5DF')
    draw = ImageDraw.Draw(im)
    draw.ellipse((166, 20, 208, 62), fill='#F1CC53')
    draw.polygon(((0, 126), (65, 52), (132, 126)), fill='#467388')
    draw.polygon(((64, 160), (164, 66), (240, 141), (240, 160)), fill='#31586D')
    draw.rectangle((0, 135, 240, 160), fill='#69954F')
    out = BytesIO()
    im.save(out, format='PNG', compress_level=0)
    return out.getvalue()


def picture(shapes, box=(48, 142, 360, 240)):
    return shapes.add_picture(BytesIO(illustration()), *(Pt(v) for v in box))


def picture_fill(page, box=(48, 142, 360, 240)):
    """A picture texture on an auto shape, distinct from a p:pic picture."""
    shape = solid(page.shapes, SHAPE.ROUNDED_RECTANGLE, box, 'FFFFFF')
    _, image_id = page.part.get_or_add_image_part(BytesIO(illustration()))
    props = shape._element.spPr
    props.remove(props.solidFill)
    fill = xml('a:blipFill')
    blip = xml('a:blip')
    blip.set(qn('r:embed'), image_id)
    fill.append(blip)
    stretch = xml('a:stretch')
    stretch.append(xml('a:fillRect'))
    fill.append(stretch)
    props.insert(list(props).index(props.ln), fill)
    return shape


def connector(shapes, start=(576, 356), end=(848, 356)):
    line = shapes.add_connector(MSO_CONNECTOR.STRAIGHT,
                                *(Pt(v) for v in (*start, *end)))
    line.line.color.rgb = RGBColor.from_string('FFFFFF')
    line.line.width = Pt(3)
    return line


def table(shapes, box=(48, 132, 864, 300), chinese=False):
    result = shapes.add_table(3, 3, *(Pt(v) for v in box))
    grid = result.table
    # Author a custom table with explicit cell styling rather than a built-in
    # Office table style. This is also how one formats a bespoke branded table.
    props = grid._tbl.tblPr
    props.attrib.clear()
    for child in list(props):
        props.remove(child)
    labels = (('区域', '项目', '状态'), ('北部', '采样', '完成'), ('南部', '分析', '进行中')) if chinese else (
        ('Team', 'Workstream', 'Status'), ('North', 'Collection', 'Complete'), ('South', 'Analysis', 'Active'))
    for r in range(3):
        for c in range(3):
            cell = grid.cell(r, c)
            cell.fill.solid()
            cell.fill.fore_color.rgb = RGBColor.from_string('DAE7EF' if r == 0 else ('EEF4F7' if r == 1 else 'E4EEE3'))
            cell.margin_left = cell.margin_right = Pt(12)
            cell.margin_top = cell.margin_bottom = Pt(10)
            cell.vertical_anchor = MSO_ANCHOR.MIDDLE
            format_paragraph(cell.text_frame.paragraphs[0], labels[r][c], 22, bold=r == 0)
            for side in ('L', 'R', 'T', 'B'):
                line = xml('a:ln' + side, w=12700)
                fill = xml('a:solidFill')
                fill.append(xml('a:srgbClr', val='48718A'))
                line.append(fill)
                cell._tc.get_or_add_tcPr().append(line)
    return grid


def group(shapes):
    outer = shapes.add_group_shape()
    solid(outer.shapes, SHAPE.ROUNDED_RECTANGLE, (90, 160, 270, 170), 'DAE7EF')
    text(outer.shapes, 'Planning', (112, 183, 220, 48), 26, bold=True)
    inner = outer.shapes.add_group_shape()
    solid(inner.shapes, SHAPE.OVAL, (405, 160, 140, 140), '4C8250')
    solid(inner.shapes, SHAPE.ISOSCELES_TRIANGLE, (580, 180, 150, 130), 'D97B28')
    # Office group coordinate spaces include child offsets and extents. A scaled
    # parent exercises composition without flattening either nested group.
    outer.width = round(outer.width * 1.12)
    outer.height = round(outer.height * 1.10)
    return outer


def archive(parts):
    out = BytesIO()
    with ZipFile(out, 'w') as target:
        for name, data in sorted(parts.items()):
            item = ZipInfo(name, (2020, 1, 1, 0, 0, 0))
            item.compress_type, item.create_system, item.external_attr = ZIP_STORED, 3, 0o600 << 16
            target.writestr(item, data)
    return out.getvalue()


def package(deck):
    out = BytesIO()
    deck.save(out)
    with ZipFile(out) as source:
        return archive({name: source.read(name) for name in source.namelist()})


def cases():
    items = {}

    deck = presentation()
    text(slide(deck).shapes, 'A practical roadmap', (96, 190, 768, 100), 44, bold=True)
    items['title'] = (deck, ['text', 'title', '16:9'])

    deck = presentation()
    page = slide(deck)
    title(page, 'From fieldwork to findings')
    shape = text(page.shapes, '', (72, 135, 816, 300), 26)
    for i, (value, level) in enumerate((('Collect source material', 0), ('Interview the team', 1),
                                       ('Record open questions', 2), ('Compare the evidence', 0),
                                       ('Publish the conclusions', 1))):
        p = shape.text_frame.paragraphs[0] if not i else shape.text_frame.add_paragraph()
        format_paragraph(p, value, 26)
        p.level = level
        props = p._p.get_or_add_pPr()
        props.set('marL', str((level + 1) * 30 * 12700))
        props.set('indent', str(-22 * 12700))
        props.append(xml('a:buChar', char='•'))
    items['bullets'] = (deck, ['text', 'bullets', 'levels-0-1-2', '16:9'])

    deck = presentation()
    page = slide(deck)
    title(page, 'A landscape in context')
    picture(page.shapes)
    text(page.shapes, 'Observation notes\nThe valley connects two survey areas.\nCompare the ridge and the lowlands.',
         (468, 140, 432, 260), 25)
    items['image-text'] = (deck, ['text', 'png', 'image-stretch', '16:9'])

    deck = presentation()
    page = slide(deck)
    title(page, 'Programme delivery')
    grid = table(page.shapes)
    grid.cell(0, 0).merge(grid.cell(0, 1))
    grid.cell(0, 0).text = 'Delivery programme'
    format_paragraph(grid.cell(0, 0).text_frame.paragraphs[0], 'Delivery programme', 22, bold=True)
    grid.cell(1, 0).merge(grid.cell(2, 0))
    format_paragraph(grid.cell(1, 0).text_frame.paragraphs[0], 'Regional teams', 22)
    items['merged-table'] = (deck, ['text', 'table', 'gridSpan', 'rowSpan', 'hMerge', 'vMerge', 'cell-borders', '16:9'])

    deck = presentation()
    page = slide(deck)
    background = page.background.fill
    background.gradient()
    background.gradient_angle = 0
    background.gradient_stops[0].color.rgb = RGBColor.from_string('DBEBF5')
    background.gradient_stops[1].color.rgb = RGBColor.from_string('5792B7')
    title(page, 'Layers of the atmosphere')
    solid(page.shapes, SHAPE.RECTANGLE, (72, 148, 430, 232), 'D97B28', 55000)
    solid(page.shapes, SHAPE.OVAL, (338, 182, 245, 245), '245A81', 65000)
    solid(page.shapes, SHAPE.ROUNDED_RECTANGLE, (620, 150, 260, 245), '4C8250', 45000)
    swatch = solid(page.shapes, SHAPE.RECTANGLE, (72, 403, 510, 22), '245A81')
    swatch.fill.gradient()
    swatch.fill.gradient_angle = 0
    swatch.fill.gradient_stops[0].color.rgb = RGBColor.from_string('245A81')
    swatch.fill.gradient_stops[1].color.rgb = RGBColor.from_string('269CA8')
    text(page.shapes, 'Translucent regions show overlapping observations.', (72, 452, 816, 54), 23)
    items['gradient-alpha'] = (deck, ['text', 'gradient-background', 'alpha', 'rect', 'ellipse', 'roundRect', '16:9'])

    deck = presentation()
    page = slide(deck)
    title(page, 'Six themes for a shared programme')
    for i in range(6):
        shape = solid(page.shapes, SHAPE.ROUNDED_RECTANGLE,
                      (48 + i % 3 * 294, 130 + i // 3 * 168, 270, 140), '245A81')
        shape.fill.fore_color.theme_color = getattr(MSO_THEME_COLOR, 'ACCENT_' + str(i + 1))
        text(page.shapes, 'Theme ' + str(i + 1), (66 + i % 3 * 294, 170 + i // 3 * 168, 232, 48), 25, 'FFFFFF', True)
    items['theme-accents'] = (deck, ['text', 'schemeClr', 'accent1', 'accent2', 'accent3', 'accent4', 'accent5', 'accent6', '16:9'])

    deck = presentation()
    page = slide(deck)
    title(page, '研究进展与下一步计划')
    text(page.shapes, '数据采集已经完成，团队正在整理分析结果。', (48, 112, 864, 62), 26)
    table(page.shapes, (48, 210, 864, 270), chinese=True)
    items['chinese'] = (deck, ['text', 'cjk-title', 'cjk-body', 'cjk-table', 'table', '16:9'])

    for wide, name in ((False, 'standard-4x3'), (True, 'wide-16x9')):
        deck = presentation(wide)
        page = slide(deck)
        width = 960 if wide else 720
        title(page, 'Space for ideas', width - 96)
        text(page.shapes, 'Review • discuss • decide', (48, 120, width - 96, 50), 26)
        solid(page.shapes, SHAPE.RECTANGLE, (48, 220, (width - 128) / 2, 214), PALETTE[0])
        solid(page.shapes, SHAPE.OVAL, (width / 2 + 16, 220, (width - 128) / 2, 214), PALETTE[1])
        items[name] = (deck, ['text', 'rect', 'ellipse', '16:9' if wide else '4:3'])

    deck = presentation()
    page = slide(deck)
    title(page, 'A programme has connected parts')
    group(page.shapes)
    text(page.shapes, 'Nested groups retain their own coordinate systems.', (90, 430, 780, 52), 24)
    items['nested-groups'] = (deck, ['text', 'grpSp', 'nested-grpSp', 'group-scale', 'roundRect', 'ellipse', 'triangle', '16:9'])

    deck = presentation()
    for i in range(20):
        page = slide(deck)
        title(page, f'Programme review — stage {i + 1:02d}')
        if i % 4 == 0:
            text(page.shapes, 'Progress this week\nEvidence collected\nAnalysis in progress', (48, 140, 432, 250), 27)
            solid(page.shapes, SHAPE.ROUNDED_RECTANGLE, (540, 140, 360, 265), PALETTE[i % 6])
            solid(page.shapes, SHAPE.OVAL, (576, 195, 84, 84), 'DAE7EF')
            solid(page.shapes, SHAPE.ISOSCELES_TRIANGLE, (740, 195, 84, 84), 'DAE7EF')
            connector(page.shapes)
        elif i % 4 == 1:
            if i == 9:
                picture_fill(page)
            else:
                image = picture(page.shapes, (98, 152, 300, 200) if i == 17 else (48, 142, 360, 240))
                if i == 5:
                    fill = image._element.blipFill
                    fill.remove(fill.find(qn('a:stretch')))
                    fill.append(xml('a:tile', tx=0, ty=0, sx=100000, sy=100000, flip='none', algn='tl'))
                elif i == 13:
                    image._element.spPr.xfrm.set('flipH', '1')
                elif i == 17:
                    image.rotation = 90
                    image._element.spPr.xfrm.set('flipV', '1')
            text(page.shapes, 'Field observations\nCompare successive records.\nShare the next actions.', (468, 145, 432, 270), 26)
        elif i % 4 == 2:
            table(page.shapes)
        else:
            group(page.shapes)
        text(page.shapes, f'Review record {i + 1} / 20', (48, 476, 864, 36), 16)
    items['twenty'] = (deck, ['text', 'png', 'image-stretch', 'image-tile', 'shape-picture-fill',
                             'flipH', 'flipV', 'quarter-rotation', 'line', 'ellipse', 'circle',
                             'triangle', 'table', 'grpSp', 'nested-grpSp', '20-slides', '16:9'])
    return items


def generate(check=False):
    payloads = {}
    for name, (deck, features) in cases().items():
        payloads[name] = package(deck)
        manifest = dict(file=name + '.pptx', slides=len(deck.slides), features=features,
                        source='generated', license='MIT')
        if name == 'twenty':
            manifest['benchmark'] = True
        save_case(name, payloads[name], manifest, check)

    valid = payloads['title']
    with ZipFile(BytesIO(valid)) as source:
        parts = {name: source.read(name) for name in source.namelist()}
    damaged = {
        'bad-truncated': valid[:len(valid) // 2],
        'bad-missing-part': archive({k: v for k, v in parts.items() if k != 'ppt/presentation.xml'}),
        'bad-invalid-xml': archive(dict(parts, **{'ppt/slides/slide1.xml': b'<p:sld xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main"><p:cSld></p:sld>'})),
    }
    for name, data in damaged.items():
        save_case(name, data, dict(file=name + '.pptx', slides=0, features=[name[4:]],
                                 source='generated', license='MIT', expected_status=5,
                                 expected_error='EXR_FORMAT'), check)
    summary_manifest(check)


def summary_manifest(check):
    """Index local manifests, retaining downloaded provenance without rewriting it."""
    entries = []
    for path in sorted(HERE.glob('*/manifest.json')):
        entry = json.loads(path.read_text(encoding='utf-8'))
        entry['file'] = (path.parent / entry['file']).relative_to(HERE).as_posix()
        entries.append(entry)
    content = json.dumps(entries, ensure_ascii=False, indent=2) + '\n'
    target = HERE / 'manifest.json'
    if check:
        assert target.read_text(encoding='utf-8') == content, 'summary manifest differs from child manifests'
    else:
        target.write_text(content, encoding='utf-8', newline='\n')
    print(f'manifest.json: {len(entries)} files, {sum(e["slides"] for e in entries)} valid slides')


def save_case(name, data, manifest, check):
    folder = HERE / name
    content = json.dumps(manifest, ensure_ascii=False, indent=2) + '\n'
    if check:
        assert (folder / manifest['file']).read_bytes() == data, name
        assert (folder / 'manifest.json').read_text(encoding='utf-8') == content, name
    else:
        folder.mkdir(parents=True, exist_ok=True)
        (folder / manifest['file']).write_bytes(data)
        (folder / 'manifest.json').write_text(content, encoding='utf-8', newline='\n')
    print(f'{name}: slides={manifest["slides"]} source={manifest["source"]} ZIP_STORED bytes={len(data)}')


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    generate(parser.parse_args().check)
